// Input: { novi, postojeci } (two listings) + optional binary "data" = screenshot of the new listing (FB).
// Compared only when both sides have an image; otherwise isti = null and the caller treats it as "not the same" (fail-open).
const { novi = {}, postojeci = {} } = $json;
const isUrl = u => /^https:\/\//.test(String(u || ''));
const hasScreenshot = !!$input.item.binary?.data;
const canCompare = isUrl(postojeci.slika) && (hasScreenshot || isUrl(novi.slika));
const opis = l => [l.cena != null ? l.cena + ' €' : null, l.m2 != null ? l.m2 + ' m²' : null, l.sobe != null ? l.sobe + ' soba' : null, [l.naselje, l.opstina].filter(Boolean).join(', ') || null, l.izvor || null].filter(Boolean).join(' · ');
const prvaSlika = hasScreenshot ? 'Prva slika je screenshot Facebook objave oglasa A (gledaj fotografije stana u njoj, ne tekst).' : 'Prva slika je naslovna fotografija oglasa A.';
const prompt = [
  'Uporedi dva oglasa za izdavanje stana u Beogradu. ' + prvaSlika + ' Druga slika je naslovna fotografija oglasa B.',
  'A: ' + opis(novi),
  'B: ' + opis(postojeci),
  'Pitanje: da li je to ISTI stan (isti prostor), a ne samo sličan stan? Isti stan = vide se isti predmeti i prostor: isti nameštaj, tepisi, prozori, podovi, zidovi, raspored. Različite fotografije istog stana su isti stan ako se vide isti predmeti. Sličan stil ili ista zgrada nije dovoljno. Ako nisi siguran, isti = false.',
  'Vrati ISKLJUČIVO jedan JSON objekat, bez objašnjenja i bez markdown ograda: {"isti": true ili false, "sigurnost": broj 0-1, "razlog": "najviše 12 reči na srpskom, latinica, ekavica"}'
].join('\n');
return { json: { novi, postojeci, prompt, urls: [novi.slika, postojeci.slika].join(','), has_screenshot: hasScreenshot, can_compare: canCompare }, binary: $input.item.binary };

// Test pairs: the same Vračar flat on 4zida and Nekretnine.rs (expected: same), and two different flats with the same price (expected: different).
const a = { id: '4zida_6afdebf9d16a4237430ff712', izvor: '4zida', url: 'https://www.4zida.rs/izdavanje-stanova/pravni-fakultet-vracar-vracar-beograd/dvosoban-stan/6afdebf9d16a4237430ff712', slika: 'https://resizer2.4zida.rs/SIEFR8TpGa4fdlS0xYjIA4w5d6MSpM-8YBpp006nRXA/rs:fill:840:0:0/bG9jYWw6Ly8vNmFmZGViZjlkMTZhNDIzNzQzMGZmNzEyLzAwNTcxZDBmOTk.jpeg', cena: 500, m2: 75, sobe: 2, opstina: 'Vračar', naselje: 'Pravni fakultet - Vračar' };
const b = { id: 'nekretnine_1674755', izvor: 'nekretnine', url: 'https://www.nekretnine.rs/oglasi/1674755/', slika: 'https://pic.nekretnine.rs/image/21374143/xxl.jpg', cena: 500, m2: 75, sobe: 2, opstina: 'Vračar', naselje: 'Hram Svetog Save - Neimar - Čubura' };
const c = { id: 'cityexpert_43463', izvor: 'cityexpert', url: 'https://cityexpert.rs/izdavanje-nekretnina/beograd/43463/jednoiposoban-stan-cerska-vracar', slika: 'https://img.cityexpert.rs/properties/470x/43000/43463/slike/cityexpert.rs_-_nekretnina_id_-_43463_-_0019_-_20210506.jpg@jpg', cena: 500, m2: 31, sobe: 1.5, opstina: 'Vračar', naselje: 'Čubura' };
return [{ json: { novi: b, postojeci: a } }, { json: { novi: c, postojeci: a } }];

// Screenshot (data) + downloaded cover photo of the existing listing (b) on one item, so Claude gets both images in one call.
// Claude only accepts image/jpeg|png|gif|webp, and some CDNs answer with octet-stream → the type is fixed here.
const prep = $('PrepareCompare').item;
const b = $input.item.binary?.b;
if (!b) return { json: { ...prep.json, can_compare: false, download_error: String($json.error?.message ?? 'no image').slice(0, 200) } };
const fix = x => ({ ...x, mimeType: /^image\/(jpeg|png|gif|webp)$/.test(x.mimeType || '') ? x.mimeType : 'image/jpeg' });
return { json: prep.json, binary: { data: fix(prep.binary.data), b: fix(b) } };

// Claude's answer → { isti: true | false | null, sigurnost, razlog }. "Same" only with confidence >= 0.7.
// Anything unclear (no images, API error, unparseable JSON) → isti = null, and the caller sends the listing normally.
const prep = $('PrepareCompare').item.json;
if ($json.can_compare === false || $json.download_error) {
  return { json: { novi: prep.novi, postojeci: prep.postojeci, isti: null, sigurnost: null, razlog: $json.download_error ? 'slika nije preuzeta' : 'nema slika za poređenje' } };
}
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || $json.text || '');
let p = null;
try { p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { p = null; }
const CYR = { 'а':'a','б':'b','в':'v','г':'g','д':'d','ђ':'đ','е':'e','ж':'ž','з':'z','и':'i','ј':'j','к':'k','л':'l','љ':'lj','м':'m','н':'n','њ':'nj','о':'o','п':'p','р':'r','с':'s','т':'t','ћ':'ć','у':'u','ф':'f','х':'h','ц':'c','ч':'č','џ':'dž','ш':'š' };
const lat = t => t.replace(/[\u0400-\u04FF]/g, ch => { const low = ch.toLowerCase(); const r = CYR[low] ?? ''; return ch === low ? r : r.charAt(0).toUpperCase() + r.slice(1); });
if (!p || typeof p.isti !== 'boolean') {
  return { json: { novi: prep.novi, postojeci: prep.postojeci, isti: null, sigurnost: null, razlog: 'Claude odgovor nije čitljiv', greska: String($json.error?.message ?? raw.slice(0, 120)).slice(0, 200) } };
}
const sig = Number.isFinite(Number(p.sigurnost)) ? Math.min(1, Math.max(0, Number(p.sigurnost))) : 0;
const razlog = typeof p.razlog === 'string' ? lat(p.razlog.trim()).slice(0, 120) : null;
return { json: { novi: prep.novi, postojeci: prep.postojeci, isti: p.isti === true && sig >= 0.7, sigurnost: sig, razlog } };
